__aicore__ void matmul_naive(
    const float* __gm__ A, const float* __gm__ B, float* __gm__ C,
    int32_t M, int32_t N, int32_t K) {
    // 简单实现，性能较差
    for (int32_t i = 0; i < M; ++i) {
        for (int32_t j = 0; j < N; ++j) {
            float sum = 0.0f;
            for (int32_t k = 0; k < K; ++k) {
